INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('you-are-ms-servant','You are Ms. Servant','君は冥土様。',2024,7.1,'Fall 2024','TV','Finished','https://media.kitsu.app/anime/48395/poster_image/medium-c4a572327a49c03c814cd66d263e3b1f.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/172190-xtxZrIvVMauR.jpg','#3b82ff','This is the story of a maid who is all alone in the world, but who finally finds a family. Told from young that her only worth is as a killer, Yuki had known nothing else except cold efficiency and following orders. Now that she has a chance to leave her past behind, she arrives at the doorstep of Hitoyoshi Yokoya, asking to be employed… as a maid?! Thus begins the journey of a former assassin learning what it means to be ‘normal’! (Source: Shogakukan)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":48395,"anilist":172190,"mal":57611}',NULL,NULL,12,datetime('now'),'you are ms servant 君は冥土様 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('the-new-gate','THE NEW GATE','THE NEW GATE',2024,6.6,'Spring 2024','TV','Finished','https://media.kitsu.app/anime/48214/poster_image/medium-ffeb2b40aaea11c2b168d9cfcf2565d3.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/170890-fQBemeo8Z4CH.jpg','#2f7bff','THE NEW GATE—an online game transformed into a life-and-death struggle for its players. Thanks to the valiant efforts of Shin, the most powerful of them all, an end to the game and freedom for everyone seemed within reach. But just moments after Shin defeats the game’s final boss, he finds himself bathed in an unknown light and transported some 500 years into the future of the in-game world. Thrown from a simple game gone wrong into a strange new land, one young swordsman of unrivalled strength is about to embark on a legendary journey! (Source: One Peace Books)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":48214,"anilist":170890,"mal":57100}',NULL,NULL,12,datetime('now'),'the new gate the new gate tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=