INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('the-foolish-angel-dances-with-the-devil','The Foolish Angel Dances with the Devil','愚かな天使は悪魔と踊る',2024,7,'Winter 2024','TV','Finished','https://media.kitsu.app/anime/47347/poster_image/medium-bc7259892e4f695db882604b2fd9f207.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/164244-Xd5RWTHAZ6wI.jpg','#ff1f4a','The story centers on Masatora Akutsu, a demon who descends to the human world in search of "idols" to motivate the corrupt demons and to boost their morale. He quickly finds a potential idol, Lily Amane, and recruits her. However, Lily turns out to be an angel, the natural enemy of Akutsu and the other demons! While Akutsu tries to corrupt Lily to protect himself and his clan, Lily decides to rehabilitate Akutsu for her own hidden ambitions. (Source: Crunchyroll)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":47347,"anilist":164244,"mal":55129}',55129,'mal',12,datetime('now'),'the foolish angel dances with the devil 愚かな天使は悪魔と踊る tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_syn