INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('the-devil-is-a-part-timer-season-2-part-2','The Devil is a Part-Timer! Season 2 Part 2','はたらく魔王さま！！2nd Season',2023,6.9,'Summer 2023','TV','Finished','https://media.kitsu.app/anime/46550/poster_image/medium-f4046ece805a5001ab7c40e9e881e215.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/155168-S9lR447kRCwF.jpg','#3b82ff','Sequel to Hataraku Maou-sama!!. Lucifer and company face new challenges, form new alliances and...now there''s a baby! Your favorite otherwordly crew returns in this continuation. (Source: Crunchyroll)',NULL,'["The Devil is a Part-Timer! Season 2 (2022)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":46550,"anilist":155168,"mal":53200}',53200,'mal',12,datetime('now'),'the devil is a part timer season 2 part 2 はたらく魔王さま 2nd season tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('ahiru-no-sora','Ahiru no Sora','あひるの空',2019,7.3,'Fall 2019','TV','Finished','https://media.kitsu.app/anime/poster_images/41399/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/101239-3xMk1BuT06HX.jpg','#ff1f4a','He may be short in stature, but Sora Kurumatani can soar and score on the basketball court! With a passion for the sport he inherited from his mother, Sora vows to her that he’ll take top prize at a high school basketball tournament… but there’s one problem. His new school’s basketball club has turned into a hangout for delinquents! Will Sora’s sheer tenacity and amazing three-point shooting change their minds and get the club up and running again?(Source: Sentai Filmworks)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":41399,"anilist":101239,"mal":37403}',37403,'mal',50,datetime('now'),'ahiru no sora あひるの空 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('nippon-sangoku-the-three-nations-of-the-crimson-sun','NIPPON SANGOKU: The Three Nations of the Crimson Sun','日本三國',2026,8.3,'Spring 2026','TV','Finished','https://media.kitsu.app/anime/50550/poster_image/medium-6621e99c7d6d6f4608f96716368c1785.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/206914-owssGq2CGhRZ.jpg','#a24bff','A revolution sparked by nuclear war, natural disaster, and misrule leads to the collapse of Japanese society. The country splits into three nations vying for hegemony, and the Sangoku era begins. Aoteru Misumi, a former agricultural officer, vows to reunify Japan. He rises through the ranks with only his knowledge and eloquence. Witness the legend of the man later hailed as a genius strategist. (Source: Amazon Prime Video)',NULL,'["Nippon Sangoku (Zoku-hen)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":50550,"anilist":206914,"mal":63375}',NULL,NULL,12,datetime('now'),'nippon sangoku the three nations of the crimson sun 日本三國 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.cata