INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('unnamed-memory','Unnamed Memory','Unnamed Memory',2024,6.7,'Spring 2024','TV','Finished','https://media.kitsu.app/anime/46921/poster_image/medium-938109ce00fff76f509072934f665fb1.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/158709-ZGCammGG4F9a.jpg','#2ee6a8','"My wish as champion is for you to descend the tower and be my wife." Seeking to end a curse thwarting his lineage, Prince Oscar sets out on a quest that leads him to a powerful and beautiful witch, Tinasha, and he demands a unique bargain: marriage. Though unenthused by the proposal, she agrees to stay in his castle for a year while researching the spell cast upon him. But beneath her beauty lies a lifetime of dark secrets that soon come to light. (Source: Yen Press, Crunchyroll)',NULL,'["Unnamed Memory Season 2 (2025)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":46921,"anilist":158709,"mal":53835}',53835,'mal',12,datetime('now'),'unnamed memory unnamed memory tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('gankutsuou-the-count-of-monte-cristo','Gankutsuou: The Count of Monte Cristo','巌窟王',2004,8,'Fall 2004','TV','Finished','https://media.kitsu.app/anime/poster_images/214/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/239-QZ7bh97wgpMn.jpg','#24d3ee','Gankutsuou is an anime loosely based on the novel The Count of Monte Cristo by Alexandre Dumas. It tells the story of Albert Morcerf, a young aristocrat who happens to befriend a wealthy nobleman, The Count of Monte Cristo, through a series of bizarre events. Fascinated by the Count''s charm, Albert invites him to meet his friends and family, all of whom happen to be part of the upper class society of Paris, France. Unfortunately, little does Albert realize that the Count has ulterior motives in mind. [Written by MAL Rewrite]',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":214,"anilist":239,"mal":239}',NULL,NULL,24,datetime('now'),'gankutsuou the count of monte cristo 巌窟王 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('uq-holder','UQ Holder!','UQ Holder! ～魔法先生ネギま!2～',2017,7,'Fall 2017','TV','Finished','https://media.kitsu.app/anime/poster_images/12273/medium.jpg','https://media.kitsu.app/anime/cover_images/12273/original.jpg','#24d3ee','In the decade since the world became aware of the existence of magic, the world has undergone massive upheaval. However, a boy named Touta lives in seclusion in a rural town far removed from these changes. His ordinary life is highlighted by his magic-using female teacher and his supportive friends. When his tranquil daily life is disrupted, he embarks on a unique adventure. (Source: ANN)',NULL,'["Negima!? Magister Negi Magi (2006)","Negima! (2005)","UQ Holder! OVA (2017)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":12273,"anilist":21855,"mal":33478}',33478,'mal',12,datetime('now'),'uq holder uq holder 魔法先生ネキ ま 2 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('love-live-sunshine','Love Live! Sunshine!!','ラブライブ！サンシャイン!!',2016,7.4,'Summer 2016','TV','Finished','https://media.kitsu.app/anime/poster_images/11745/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/21584-mvyzC8r4cq6E.jpg','#ffc247','Chika Takami, a self-proclaimed normal girl, has never been involved in any clubs and lacked any notable talents. However, after a visit to Tokyo, she discovers a stage where even an ordinary girl like her could shine—the world of school idols. Inspired by the former superstar school idol group μ''s, Chika is determined to start her own school idol club in her seaside hometown at Uranohoshi Girl''s High School. But even before gathering any students to join the group, the aspiring school idol finds her greatest obstacle to be student council president Dia Kurosawa who stands firmly against the creation of the club. Just when it seems there is no hope, Chika meets Riko Sakurauchi, a transfer student from Otonokizaka High School, home of μ''s. Somewhat shy but a talented piano player, Chika believes her to be a promising recruit, though convincing her to join is easier said than done. In spite of that, Chika chooses to charge forward and overcome the obstacles keeping her from forming a school idol group that shines as bright as the nine that came before her. [Written by MAL Rewrite]',NULL,'["Love Live! The School Idol Movie (2015)","Love Live! Sunshine!! Season 2 (2017)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":11745,"anilist":21584,"mal":32526}',NULL,NULL,13,datetime('now'),'love live sunshine ラフ ライフ サンシャイン tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('in-the-land-of-leadale','In the Land of Leadale','リアデイルの大地にて',2022,7,'Winter 2022','TV','Finished','https://media.kitsu.app/anime/44186/poster_image/medium-11fae7d224a76dbe351ed9a8d9c1d99d.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/130166-VfxhkKvXFppG.jpg','#2ee6a8','Due to a terrible accident, Keina Kagami is forced to live on life support in order to survive. The only way for her to be free is within the VRMMORPG "Leadale." One day, her life support stops functioning, and Keina loses her life. But when she wakes up, she finds herself in the world of Leadale 200 years in the future. She is now the high elf Cayna, who possesses lost skills and OP statuses and becomes closer to the other inhabitants of this world. But among those inhabitants happen to be the "children" she made in character creation?! (Source: Crunchyroll)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":44186,"anilist":130166,"mal":48239}',48239,'mal',12,datetime('now'),'in the land of leadale リアテ イルの大地にて tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('punch-line','PUNCH LINE','パンチライン',2015,6.9,'Spring 2015','TV','Finished','https://media.kitsu.app/anime/poster_images/10038/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/20964-etLaKGc0pXvo.jpg','#24d3ee','A bus has been hijacked by armed robbers, but not to worry—vigilante fighter Strange Juice is on the scene. With a Bam, Pow, and Crack, she sends those baddies flying right out of the bus! All except the mastermind, unfortunately. To get past him, she’ll need some help from… a panty-powered superhero!? Yuuta Iridatsu is a pretty typical high school kid. Except for his tendency to faint every time he sees a girl’s panties, of course. After his encounter with Strange Juice, his soul gets separated from his body. But for Yuuta, this is more of a blessing than anything else, as it enables him to wander around unseen, looking up skirts and making trouble as much as he wants. For some reason, though, every time Yuuta gets too excited and faints, an asteroid hits the Earth. What gives!? Yuuta figures he’s got no choice. He has to find out why his love of panties threatens to destroy the world. And probably stop it. Right after this one last panty shot!',NULL,'["Punch Line MAX"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":10038,"anilist":20964,"mal":28617}',NULL,NULL,12,datetime('now'),'punch line ハ ンチライン tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
