INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#1','shaman-king',1,'The Boy who Dances with Ghosts','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3915/original.jpg','Trying to prove that Yoh Asakura, the new transfer student, can talk to spirits, thirteen-year-old Manta Oyamada (Morty) gets in trouble with the gang of Ryu of the Wooden Sword. When everything seems bound to go bad for him, however, he gets help from an unexpected source.','[]','2001-07-04','3915');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#2','shaman-king',2,'Waiting Samurai','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3916/original.jpg','Yoh wants the spirit of Amidamaru, the devil samurai, to join him as his Main Spirit. Amidamaru is waiting for someone, though, and can''t leave the cemetery. Yoh tries to find out who the samurai is waiting for, while Ryu of the Wooden Sword searches for revenge.','[]','2001-07-11','3916');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#3','shaman-king',3,'Another Shaman','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3917/original.jpg','Yoh is challenged to a fight by Ren Tao, an arrogant Shaman who believes Spirits are only tools.','[]','2001-07-18','3917');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#4','shaman-king',4,'Hyoi 100','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3918/original.jpg','Yoh is injured in the fight with Ren, but there is no time to rest: to defeat his challenger, he must learn to unify his will with Amidamaru''s, and reach the one-hundred percent Hyoi Gattai.','[]','2001-07-25','3918');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#5','shaman-king',5,'The Shaman that is Mature for Her Age','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3919/original.jpg','Yoh''s fiancée, Anna Kyoyama, arrives into town to coach Yoh for the Shaman Fight. Her methods seem abusive, but the training comes on handy when Yoh is attacked by Kyonshii commanded by the Tao family.','[]','2001-08-01','3919');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#6','shaman-king',6,'Kung Fu Master','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3920/original.jpg','Manta brings Yoh, Anna and Amidamaru to watch a movie about his idol, the late Kung-Fu fighter Lee Pai-Long. Things get dangerous when Lee Pai-Long''s corpse attacks them, commanded by Ren''s sister, Jun Tao.','[]','2001-08-08','3920');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#7','shaman-king',7,'Pailong, Fists of Fury','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3921/original.jpg','Freed from his enslavement, Pai-Long goes berserk and aimlessly attacks Yoh. To fight him, Anna summons the spirit of Pai-Long''s late master, Shamon.','[]','2001-08-15','3921');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#8','shaman-king',8,'Shaman Life','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3922/original.jpg','After witnessing Yoh''s fight against Pai-Long, Ryu of the Wooden Sword decides that he wants to become a Shaman too. Meanwhile, Gei Yin, another Shaman under the Tao family, arrives from China to have a go against Yoh.','[]','2001-08-22','3922');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#9','shaman-king',9,'The Boy from the North','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3923/original.jpg','Yoh gives shelter to a traveler called HoroHoro, only to have Anna worry that he might be a Shaman trying to eliminate opponents before the start of the Shaman Fight.','[]','2001-08-29','3923');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#10','shaman-king',10,'The Fate of 600 Years','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3924/original.jpg','Ryu of the Wooden Sword believes that he''ll never be able to become a Shaman. Down and unhappy, he is possessed by the spirit of Tokageroh, a bandit from 600 years ago who wants to get revenge on Amidamaru.','[]','2001-09-05','3924');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#11','shaman-king',11,'Rain that Falls in Spring','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3925/original.jpg','When Tokageroh kidnaps Manta and threatens to kill him with the Harusame, Amidamaru has to choose between the safety of his friends and the sword he values so much.','[]','2001-09-12','3925');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#12','shaman-king',12,'The Star that Signals the Beginning','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3926/original.jpg','After breaking Amidamaru''s sword, Ryu becomes even more depressed, and Yoh looks for a solution. Meanwhile, the star that signals the beginning of the Shaman Fight descends from the sky.','[]','2001-09-19','3926');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#13','shaman-king',13,'Over Soul','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3927/original.jpg','To enter the Shaman Fight, Yoh must hit, at least once, the Shaman Fight priest Silva. The task is not easy, though, because Silva uses a different technique to fight with his guardian spirits.','[]','2001-09-26','3927');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#14','shaman-king',14,'Shaman Fight','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3928/original.jpg','Yoh''s first opponent in the Shaman Fight is HoroHoro, and things get awkward between them both when HoroHoro''s younger sister and Anna seem to forget that "opponent" and "friend" are not antonyms.','[]','2001-10-03','3928');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#15','shaman-king',15,'Bone Killers','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3929/original.jpg','Yoh''s second opponent is an eerie doctor called Faust VIII, who Silva believes to be an extremely dangerous man. This is proven to be true when the doctor kidnaps Manta.','[]','2001-10-10','3929');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#16','shaman-king',16,'Faust Love','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3930/original.jpg','The fight against Faust continues. As the doctor harasses Manta, Yoh loses his calm and ends up in a disadvantageous position. Danger only increases when Faust summons the spirit of his late wife, Eliza.','[]','2001-10-17','3930');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#17','shaman-king',17,'Journey to the Best Place','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3931/original.jpg','Trying to protect Manta, Yoh pushes his friend away and returns to his grandfather''s house to train for the second round. Distraught, Manta embarks in a journey with Ryu of the Wooden Sword to find his friend. On their way, they''re followed by Elly and Milly, two Shamans trying to eliminate opponents before the Shaman Fight.','[]','2001-10-24','3931');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#18','shaman-king',18,'Yoh','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3932/original.jpg','To improve his Shaman abilities, Yoh entered the Hole of Yomi, a place where there is no light and sound. Manta, Anna, Amidamaru and a girl called Tamao wait for him to come back. Meanwhile, Elly and Milly reach their location.','[]','2001-10-31','3932');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#19','shaman-king',19,'Big Soul of the Two','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3933/original.jpg','Ren''s conflicts and doubts about his way of life and his role on the Tao family are brought into arena when he and Yoh start the third fight.','[]','2001-11-07','3933');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#20','shaman-king',20,'Soul Mata Cemetery','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3934/original.jpg','Yoh''s tranquility of mind breaks Ren''s resolve, and their fight comes to a draw. Realizing that his ways were wrong, Ren decides to fight his uncle, the source of all his hatred. It all goes downhill, though, when he and June are captured.','[]','2001-11-14','3934');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#21','shaman-king',21,'Believe','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3935/original.jpg','Sneaking away from Yoh''s house to rescue Ren, Yoh, Manta and HoroHoro meet a duo of Shaman singers, whose technique sends spirits to the other world.','[]','2001-11-21','3935');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#22','shaman-king',22,'Our Deadly Blows','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3936/original.jpg','Yoh, Manta, HoroHoro and Ryu of the Wooden Sword reach the Tao family''s main house. On their way to rescue Ren and June, they are forced to fight the five Kyonshii who are known as the Five Deities.','[]','2001-11-28','3936');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#23','shaman-king',23,'Awakened, Nyan Nyan Doushi','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3937/original.jpg','The most powerful of the Five Deities turns out to be Lee Pai-Long''s late master, Shamon. His Kung Fu moves get the best of the quartet, and only Pai-Long himself can defeat him.','[]','2001-12-05','3937');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#24','shaman-king',24,'Invulnerable En Tao','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3938/original.jpg','The group of Shamans finally meets Ren''s uncle, En Tao. Nonetheless, not even their best techniques seem to harm the enormous man; to defeat him, they need to figure out the secret behind his invulnerability.','[]','2001-12-12','3938');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#25','shaman-king',25,'To Shaman’s Journey','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3939/original.jpg','Yoh, Ryu, Ren and HoroHoro say goodbye to their friends and family before going to America for the second preliminary tournament. However, before they can leave, the mysterious Hao shows up to assess the group''s strength.','[]','2001-12-19','3939');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#26','shaman-king',26,'Big America','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3940/original.jpg','The quartet''s airplane falls in the desert, and the four Shamans are left to find their way to the Patch village, while being targeted by a group of eccentric Shaman fighters.','[]','2001-12-26','3940');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#27','shaman-king',27,'Dawsing Revolution','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3941/original.jpg','Ryu of the Wooden Sword meets a Shaman called Lyserg, who is interested on finding powerful allies. His methods of testing his potential companions, however, aren''t the most orthodox, and things get dangerous for the quartet when he puts his Dowsing technique into use.','[]','2002-01-09','3941');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#28','shaman-king',28,'Lyserg Avenger','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3942/original.jpg','Lyserg tells Yoh, Ryu, Ren and HoroHoro his story, not knowing that he is being chased by the Shamans he has hurt on his search for powerful allies.','[]','2002-01-16','3942');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#29','shaman-king',29,'Burning Tenacity','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3943/original.jpg','Lyserg feels down after a run-in with Hao, whose powers can stop even a powerful blizzard. Trying to cheer him up, Ryu tells him how he became a Shaman. Meanwhile, Anna and Manta leave to a mysterious place called the Mount Terror.','[]','2002-01-23','3943');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#30','shaman-king',30,'The Silver Oracle Bell','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3944/original.jpg','When Milly''s Oracle Bell is stolen, Yoh and the others lend a hand to find the culprit.','[]','2002-01-30','3944');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#31','shaman-king',31,'The Forest of Faeries','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3945/original.jpg','Yoh and the others stop by a ghost town, place of rest of some bored spirits.','[]','2002-02-06','3945');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#32','shaman-king',32,'Horo-Horo’s Taste of a Bitter Friend','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3946/original.jpg','While looking for food in a forest, HoroHoro meets a Shaman called Allen, who uses his abilities to vandalize a company that is harming the forest.','[]','2002-02-13','3946');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#33','shaman-king',33,'The Mysterious Asakura','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3947/original.jpg','The story of Hao and the Asakura family is revealed when Yoh''s grandfather asks Anna to take the book that contains Hao''s teachings to Yoh. Meanwhile, Ashiru, one of Hao''s followers, challenges the group to kill Yoh''s friends, not knowing that the X-Laws are about to intervene in the fight.','[]','2002-02-20','3947');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#34','shaman-king',34,'American Hot Springs','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3948/original.jpg','Yoh and the others spend the night in a Hot Spring district, only to be targeted by a rival of Sharona, who has the power of creating illusions.','[]','2002-02-27','3948');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#35','shaman-king',35,'The Vampire Legend','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3949/original.jpg','The group is attacked by another of Hao’s followers, who claims to be a vampire. Meanwhile, Anna and Manta leave to America.','[]','2002-03-06','3949');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#36','shaman-king',36,'Angel''s Pistol','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3950/original.jpg','Lyserg has been bitten by Boris, and the others need to understand the mystery behind the vampire''s technique to defeat him - all this while the X-Laws try to break into the church to destroy them all.','[]','2002-03-13','3950');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#37','shaman-king',37,'Joke King','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3951/original.jpg','Still depressed because Lyserg left with the X-Laws, the four Shamans meet a boy called Chocolove, who wants to become the world''s greatest comedian through the Shaman Fight. In the meantime, Faust VIII and Anna make a deal.','[]','2002-03-20','3951');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#38','shaman-king',38,'The Legend of Seminoa','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3952/original.jpg','Guided by Chocolove''s information, the group reaches the house of Lilirara, a descendant from the warriors of the Seminoa tribe, who fought on the last Shaman Fight and know where the Patch Village is.','[]','2002-03-27','3952');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#39','shaman-king',39,'Flower Team','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3953/original.jpg','The Flower Team, three girls who are part of Hao''s group, face Yoh to make him realize he needs to become stronger. Meanwhile, trying to find Yoh, Anna meets Hao for the first time.','[]','2002-04-03','3953');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#40','shaman-king',40,'Super Notes on Shamanic Powers','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3954/original.jpg','Led by Anna, Yoh and the others come into contact with the source of Hao''s power.','[]','2002-04-10','3954');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#41','shaman-king',41,'Explosive Over Souls','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3955/original.jpg','Under the eyes of Marco, Lyserg and Hao, Yoh and the others face the Flower Team a second time to test their new strength.','[]','2002-04-17','3955');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#42','shaman-king',42,'Spirit of Sword','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3956/original.jpg','Ambushed by the X-Laws, Yoh and his friends must decide how they will take the knowledge that Yoh is Hao''s twin. Meanwhile, Amidamaru''s spirit evolves.','[]','2002-04-24','3956');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#43','shaman-king',43,'Battle of Gods','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3957/original.jpg','The group reaches a town where many God-class Shamans stop and rest before moving on to Patch Village. While there, they get to see the real power of the X-Laws'' Leader, Iron Maiden Jeanne.','[]','2002-05-01','3957');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#44','shaman-king',44,'One More Push','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3958/original.jpg','The Icemen group, who pride themselves on enduring the world''s harshest temperatures, challenge Yoh to a fight, and only Yoh''s true strength will make them see reason. Yoh win the match','[]','2002-05-08','3958');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#45','shaman-king',45,'Great Spirits','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3959/original.jpg','The group finally makes it to Patch Village, but there''s another challenge they have to face before they are allowed to enter. When they realize it''s an illusion and everyone passes, Silva appears and takes Yoh to the village. For the next round of the tournament, Yoh''s group divides into groups of three.','[]','2002-05-15','3959');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#46','shaman-king',46,'The Dead Spirit of Tao','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3960/original.jpg','Ren''s integrity is questioned when Gei Yin, who used to be under service of the Tao family, claims that he betrayed her and her family by forgetting the Tao family pride and leaving them all behind.','[]','2002-05-22','3960');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#47','shaman-king',47,'Really Naive','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3961/original.jpg','Ryu meets a girl called Anith, who shares with him the wish of finding the Best Place, but whose dream is crushed by her abusive fiancé. When their team turns out to be Funbari Hot Spring Team’s next opponents, Ryu vows to remind her of the true meaning of leaving your dream to another.','[]','2002-05-29','3961');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#48','shaman-king',48,'Dragon Missionary','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3962/original.jpg','HoroHoro has to prove himself worthy of being the Shaman King to his team’s next opponents, some eccentric missionaries who believe that the young cannot deal with the burden of winning the Shaman Fight.','[]','2002-06-05','3962');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#49','shaman-king',49,'Doctor Doctor','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3963/original.jpg','Manta struggles to understand Faust’s behavior towards Funbari Hot Spring’s next opponents, a group of Shamans whose Oversoul style damages their bodies.','[]','2002-06-12','3963');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#50','shaman-king',50,'I Have a Darkness in My Heart','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3964/original.jpg','When Ren and HoroHoro’s fears become weapons against them because of their next opponent’s power of illusions, it’s up to Chocolove to win over his own darkness and save his partners.','[]','2002-06-19','3964');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#51','shaman-king',51,'Shaman Hunt','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3965/original.jpg','The Fudou Myouou, an organization of monks who believe all spirits attached to Shamans are evil spirits, want to send Amidamaru to the other world. When the samurai starts to believe that he is indeed an evil spirit, Yoh has to remind him of their true relationship, and save Mosuke’s spirit and Manta’s body in the process.','[]','2002-06-26','3965');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#52','shaman-king',52,'Special Training!? Everyone Gathers','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3966/original.jpg','Yoh and the others are troubled because they still aren''t a match to Hao. Meanwhile, the Lily Five wait for their first match, only to find out it is going to be much more troublesome than they thought.','[]','2002-07-03','3966');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#53','shaman-king',53,'Bye Bye','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3967/original.jpg','The Lily Five group is willing to face Hao, and Yoh is unsure of what to do: if it is their choice, is it okay to let them fight and die? Meanwhile, Ren tries to overcome his limits to face Yoh’s father.','[]','2002-07-10','3967');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#54','shaman-king',54,'The Eighth Angel','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3968/original.jpg','Lyserg desperately wishes to be bestowed with an angel by the Iron Maiden Jeanne, and Morphine, Yoh and the others fear that he is now too far from their reach.','[]','2002-07-17','3968');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#55','shaman-king',55,'Gate of Babylon','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3969/original.jpg','Manta’s plan of cheering Ryu up turns upside down when he is kidnapped by the X-Laws, who want to lure Yoh into their trap, the Gate of Babylon. In his determination to be strong enough to help Yoh, Manta discovers something about his computer, and the X-Laws get in trouble when Hao intervenes in the fight.','[]','2002-07-24','3969');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#56','shaman-king',56,'Door of Babylon','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3970/original.jpg','The determination of the X-Laws, even in face of certain death, allows the Iron Maiden to recover and open the Gate of Babylon. However, their plan might bring exactly the opposite of what they were trying to achieve, when Hao takes advantage of their weakness.','[]','2002-07-31','3970');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#57','shaman-king',57,'The Shaman Fight Ends?','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3971/original.jpg','After consuming Jeanne’s spirit, Hao decides to take the Great Spirit by force. Meanwhile, Yoh and the others recover from the battle in the Gate of Babylon, and muster their will to fight to prepare for the last battle.','[]','2002-08-07','3971');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#58','shaman-king',58,'Flaming Angel','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3972/original.jpg','Yoh and Ren learn other, stronger ways of manifesting their Furyoku, and the X-Laws get ready for their last stand, as Lyserg finally discovers his true strength upon witnessing the sacrifice of his comrades.','[]','2002-08-14','3972');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#59','shaman-king',59,'Holy Ground of the Stars','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3973/original.jpg','Yoh and the others are called to the Holy Ground of the Stars, wherein lies the Great Spirit. While Manta follows Hao throughout the place and Yoh tries to stop his twin’s advance, Yoh’s companions have to face Hao’s followers, who received the gift of strength from their master.','[]','2002-08-21','3973');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#60','shaman-king',60,'Friend','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3974/original.jpg','When Ren is heavily injured, HoroHoro, Ryu, Faust, Chocolove and newly arrived Lyserg fight to protect him, revealing, to Hao’s followers, what is the true meaning of companionship. Meanwhile, Anna’s rosary of 1080 beads is bestowed with the power of sealing Hao.','[]','2002-08-28','3974');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#61','shaman-king',61,'Eternal Farewell','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3975/original.jpg','The big fight between Hao and Yoh starts, as his friends try to defeat the Great Spirits’ guardians, and stop Hao’s plans of uniting with the Great Spirits. However, things take a darker turn when Hao lives up to his promise of asking for Yoh’s body back…','[]','2002-09-04','3975');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#62','shaman-king',62,'Die! Collision!','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3976/original.jpg','Driven by anger and grief, Yoh’s companions fight for revenge against Hao, who has just absorbed his twin’s soul. However, Manta is there to remind them that their true strength does not come out of violence and hatred, and help them in a desperate last attempt to stop Hao.','[]','2002-09-11','3976');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#63','shaman-king',63,'A Place Where I Belong','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3977/original.jpg','His friends’ belief and the seeds of hope Yoh has sown wherever he went work as an anchor for his return, but the fight against Hao hasn’t ended yet.','[]','2002-09-18','3977');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('shaman-king#64','shaman-king',64,'Epilogue','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/3978/original.jpg','Hao''s, whose power is born of his invincibility alone, and Yoh''s, whose power is given to him by his friends and companions, face off for the last time.','[]','2002-09-25','3978');
