INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ahiru-no-sora#1','ahiru-no-sora',1,'The Ugly Duckling','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/268325/original.png','Sora is determined to join the basketball club, but the club’s members are determined to goof off instead of practice. Sora’s solution? A five-on-one game, winner takes all!','[{"kind":"outro","label":"Ending","start":1320,"end":1425}]','2019-10-02','268325');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ahiru-no-sora#2','ahiru-no-sora',2,'Boys Without Talent','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/268326/original.png','Sora’s skill and enthusiasm remind Momoharu of what it means to be passionate about basketball — but will Momoharu keep his promise to get serious about the game again?','[{"kind":"outro","label":"Ending","start":1321,"end":1440}]','2019-10-09','268326');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ahiru-no-sora#3','ahiru-no-sora',3,'Momoharu’s Wings','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/269667/original.jpg','Punks from Maru High have challenged Sora’s team to a basketball match, but how good is their team, anyway? Sora goes undercover to investigate!','[{"kind":"intro","label":"Opening","start":1,"end":91},{"kind":"outro","label":"Ending","start":1305,"end":1391}]','2019-10-16','269667');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ahiru-no-sora#4','ahiru-no-sora',4,'First Flight','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/269668/original.jpg','The day of the match against Maru High is here, and Sora can’t wait to hit the court! But do the punks of Kuzu High stand a chance against their more experienced opponents?','[{"kind":"outro","label":"Ending","start":1321,"end":1440}]','2019-10-23','269668');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ahiru-no-sora#5','ahiru-no-sora',5,'Broken Wings','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/269669/original.png','Tokitaka thinks he’s found a way to shut Sora out of the paint, but the pint-sized powerhouse still has a trick up his sleeve that could turn this game around!','[{"kind":"outro","label":"Ending","start":1282,"end":1365}]','2019-10-30','269669');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ahiru-no-sora#6','ahiru-no-sora',6,'Now''s the Time','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/269670/original.jpg','Sora’s new strategy has put him in the crosshairs of the defense, and things are looking bleak. Luckily for him, Kuzu High’s secret weapon is ready to take the court!','[{"kind":"intro","label":"Opening","start":40,"end":128},{"kind":"outro","label":"Ending","start":1297,"end":1387}]','2019-11-06','269670');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ahiru-no-sora#7','ahiru-no-sora',7,'The Troublesome Freshman','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/269671/original.png','After taking an exhausted Sora home post-game, Madoka learns the truth about Sora’s basketball-star mother and the reasoning behind his grand ambitions.','[{"kind":"intro","label":"Opening","start":32,"end":123},{"kind":"outro","label":"Ending","start":1323,"end":1440}]','2019-11-13','269671');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ahiru-no-sora#8','ahiru-no-sora',8,'The Duck and the Kite','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/269672/original.jpg','Kite only cares about two things: the ball and the basket. Team bonding? He''ll pass, thanks... but will he change his tune when he learns he shares a common dream with Sora?','[{"kind":"outro","label":"Ending","start":1322,"end":1434}]','2019-11-20','269672');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ahiru-no-sora#9','ahiru-no-sora',9,'Kite, His Ball, and the Team’s Pain','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/269673/original.jpg','Kite’s fate was sealed the moment he laid hands on those upperclassmen. Luckily for him, Sora has never been one to give up without a fight.','[{"kind":"outro","label":"Ending","start":1415,"end":1440}]','2019-11-27','269673');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ahiru-no-sora#10','ahiru-no-sora',10,'Manager','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/269674/original.jpg','All Sora wanted was to get his “wings” repaired. He didn’t count on getting a super cute, super clumsy team manager in the bargain!','[{"kind":"intro","label":"Opening","start":7,"end":97},{"kind":"outro","label":"Ending","start":1330,"end":1440}]','2019-12-04','269674');
