INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#1','joshiraku',1,'Normal Dialogue / Different Clothes / Shouting Instructions','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99109/original.jpg','As five young rakugo comedians, Marii, Kigurumi, Tetora, Gankyō and Kukuru, receive an invitation to a casual dress party, they ponder over what it exactly means to dress casually. Later, the discussion turns to whether everyone prefers dogs or cats.','[]','2012-07-05','99109');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#2','joshiraku',2,'Backstage Riches / Three Towers and a Vow / Cold Girl','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99110/original.jpg','The girls talk about what they would do if they won the lottery, leading them to suspect one of them may be a winner. Later, they visit the Tokyo Tower where more strange conversations are to be had. Afterwards, a discussion about vaccination turns into a bout of imaginary pregnancy.','[]','2012-07-12','99110');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#3','joshiraku',3,'Heartless Bath / Going to Asakusa / Sanada''s Little Zoo','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99111/original.jpg','Marii ends up having to prove that she''s not a crossdressing boy. Later, the girls visit Asakusa where they try their hand at some fortunes. This leads the girls to discuss why Tetora has such great luck and always seems to avoid danger.','[]','2012-07-19','99111');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#4','joshiraku',4,'The Young Girl With Glasses / A Good, Good Fort / Eyes of the Rabbit','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99112/original.jpg','As Gankyō exhibits some violent behavior, the girls discuss the stereotypes that come when a girl wears glasses. Later, as Kukuru gets trainsick, the girls try to come up with various ailments for her. Afterwards, on the night of a full moon, the girls sit and discuss moon-related topics before being attacked by a large rabbit.','[]','2012-07-26','99112');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#5','joshiraku',5,'Praise the Girl / Small Holey Town / Farewell to Glasses','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99113/original.jpg','The girls attempt to cheer Kukuru up by holding an out-of-season Christmas party. Later, the girls visit Harajuku, where Marii gets anxious over a crépe. Afterwards, the gang discuss how they all have different types of skin, making Gankyō feeling left out.','[]','2012-08-02','99113');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#6','joshiraku',6,'Four Wows / Musashi Scenery / The Servant''s Vengeance','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99114/original.jpg','Having forced Gankyō out of the group during the previous episode, the rest talk about the benefits of having a group of four. Gankyō soon gets revenge by locking everyone in the dressing room. After eventually being let back into the group, Gankyo is reluctantly placed at the bottom of the heirachy but soon has aspirations of winning an election.','[]','2012-08-09','99114');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#7','joshiraku',7,'Delinquents are Scary / Fish Story / Dressing Room Files','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99115/original.jpg','The sudden appearance of Hina dolls in the dressing room somehow leads to the girls deciding to act like delinquents so they will marry early. Later, the girls get up early to go to a fish market. Afterwards, the girls search for things that might be using up electricity, becoming oblivious to the non-electric horrors hidden throughout the room.','[]','2012-08-16','99115');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#8','joshiraku',8,'Bag of Gold / Totter / Is It Over Yet?','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99116/original.jpg','Marii laments how she''s always the last to go in various things, particularly when it comes to picking out envelopes of New Year''s money. Later, the girls head to the Sugamo district and check out the various spots. Afterwards, the gang needlessly worry that Kukuru might contract the May Blues, randomly choosing to take on "Blues" from other months.','[]','2012-08-23','99116');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#9','joshiraku',9,'Butt-tofu / The Bear of Ueno / Sleep talking','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99117/original.jpg','As school holidays roll in, the girls try and come up with ways to make rakugo more appealing to younger audiences. Later, the gang visit the zoo and discuss the curiosities of all the animals. Afterwards, the gang gets taste for lucky events which keep occurring whenever Marii falls asleep, constantly trying to make her sleep to reap the benefits.','[]','2012-08-30','99117');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#10','joshiraku',10,'Pumpkin Band / Battle of Shinjuku / Cavity Shore','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99118/original.jpg','On Halloween, the girls try to tailor the holiday to be more Japanese-esque. Later, the girls visit the Kabukichou entertainment district and observe how it''s changed over the years. Afterwards, Marii is plagued with tooth cavities.','[]','2012-09-06','99118');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#11','joshiraku',11,'Family Play / Sakai Five / Tree Tragedy','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99119/original.jpg','As the girls have a fake summer beach trip in the dressing room, they discuss the different designs of school swimsuits. Then, the girls go sightseeing in Musashi-Sakai and pay their respects to the company responsible for animating them. Lastly, the girls have a Christmas party, but the tree that Tetora ordered online completely fills the dressing room, causing them to try and reunite (but end up fighting each other) in the Amazon-like jungle.','[]','2012-09-13','99119');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#12','joshiraku',12,'The Dreamer Strikes Back / Gotta / Blacks','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99120/original.jpg','When Tetora asks everyone about their first dream of the new year, Kukuru grows upset as she has yet to have one. So, the girls attempt to act out a "first dream" to cheer her up. Later, the gang visits Roppongi, where they look at structural artwork and Marii travels through time to see the city during its economic bubble. Finally, the girls try to cool off during the summer by mentioning scary things to give themselves chills and eventually by painting everything blue.','[]','2012-09-20','99120');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshiraku#13','joshiraku',13,'Character Guts / Mighty Akiba / Sprinkle Lectures','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/99121/original.jpg','As the girls come to terms that the show has reached its last episode, a new character appears: an exasperating girl named Uzannu Uzattei. While discussing whether or not "once" is truly enough, Uzannu''s personality irritates everyone and threatens the character balance of the show. After the girls drive her away, they visit Akihabara. Later, the girls debate about how some things should be left as they are. Finally, the show ends with one last rakugo performance by Marii.','[]','2012-09-28','99121');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('angel-beats-specials#1','angel-beats-specials',1,'Stairway to Heaven','27:00',1620,'','Set between episodes four and five, Yuri orders the SSS to pretend to enjoy the day hyperactively, as part of "Operation High Tension Syndrome". Yuri hopes that Angel would lead them straight to God, and failure of the operation results in a week-long fasting. Everyone disperses with their fake enthusiasm, and a "tension meter" rates their excitement levels for every activity and outburst. Eventually when gathered up, they have a sports festival, involving the NPCs too. Meanwhile, Yuri oversees the whole operation, until Angel wanders in to intervene after Shiina''s interruption. Angel moves on to "report", and the SSS follow her to an underground greenhouse, where they assumed housed God. Instead, they find an ordinary garden, tended by Angel. Vexed, Yuri imposes the fasting and ends up starving the SSS.','[]','2010-12-22','86051');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('angel-beats-specials#2','angel-beats-specials',2,'Hell''s Kitchen','27:00',1620,'','Set between episodes two and three, during Golden Week, Yuri arranges for the SSS to go on a deadly picnic, which involves most of the members trying to kill each other with various traps and gadgets. As the boys largely fall victim to various traps, leaving just Otonashi alive, Girls Dead Monster members Miyuki and Shiori attempt to lead Iwasawa into various pitfalls, only for her to survive each one while remaining completely oblivious. They attempt to use their last trap, a dreadful concoction, but it instead lands on Hisako, who transforms into a blood-thirsty monster that not even Angel can stop.','[]','2015-06-24','173451');
