INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-comic-artist-his-assistants#5','the-comic-artist-his-assistants',5,'Park Shock \ Someday \ Using Close Friends for Reference','13:00',780,'https://media.kitsu.app/episodes/thumbnails/160186/original.jpg','Aito, deppressed that his manga ranks dead last, meets an unusual fan int he park, Ashisu dreams of being a professional, and our favorite mangaka uses his friends as drawing references.','[]','2014-05-06','160186');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('the-comic-artist-his-assistants#6','the-comic-artist-his-assistants',6,'Let''s Go to a Hot Spring','13:00',780,'https://media.kitsu.app/episodes/thumbnails/160192/original.jpg','Aito decides to spend his royalty check on the girls, inviting them to a relaxing vacation to the hot springs. But as it always is with Aito, he has ulterior motives...','[]','2014-05-13','160192');
